1416	    const torch::Tensor& expert_W2,
1417	    const torch::Tensor& expert_b2,
1418	    int N, int d_model, int num_experts, int expert_hidden,
1419	    torch::Tensor& expert_counts,
1420	    int peer_topk = 4)
1421	{
1422	    auto lopt = torch::TensorOptions().dtype(torch::kLong).device(feat.device());
1423	
1424	    // Per-element expert MLP weights (shared codebook, indexed per element).
1425	    auto scalar_in = feat.mean(1);                                          // [N]
1426	    auto W1 = expert_W1.reshape({num_experts, -1}).to(torch::kFloat32);     // [E, H]
1427	    auto b1 = expert_b1.reshape({num_experts, -1}).to(torch::kFloat32);     // [E, H]
1428	    auto W2 = expert_W2.reshape({num_experts, -1}).to(torch::kFloat32);     // [E, H]
1429	    auto b2 = expert_b2.reshape({num_experts, -1}).to(torch::kFloat32);     // [E, 1]
1430	    const int H = W1.size(1);
1431	
1432	    // Apply the per-element MLP for a [N, A] block of expert indices, weighted
1433	    // by routing_w [N, A], reduced over A. scalar_in [N] is the (broadcast) MLP
1434	    // input. Returns [N].
1435	    auto run_experts = [&](const torch::Tensor& expert_idx,       // [N, A] long
1436	                           const torch::Tensor& routing_w) {      // [N, A] float
1437	        const int64_t A = expert_idx.size(1);
1438	        auto flat = expert_idx.reshape({-1});                     // [N*A]
1439	        auto g_W1 = W1.index_select(0, flat).reshape({N, A, H});  // [N,A,H]
1440	        auto g_b1 = b1.index_select(0, flat).reshape({N, A, H});
1441	        auto g_W2 = W2.index_select(0, flat).reshape({N, A, H});
1442	        auto g_b2 = b2.index_select(0, flat).reshape({N, A});     // [N,A]
1443	        auto si   = scalar_in.reshape({N, 1, 1});                 // [N,1,1]
1444	        auto hidden = (g_W1 * si + g_b1).clamp_min(0.0f);         // [N,A,H] ReLU
1445	        auto out    = (g_W2 * hidden).sum(2) + g_b2;              // [N,A]
1446	        return (out * routing_w).sum(1);                          // [N]
1447	    };
